$ cat Barrier.java
public class Barrier {
    static Object[] refs;
    static long[]   prims;
    public static void main(String[] a) {
        int N = 1 << 20, R = 300;
        refs  = new Object[N];
        prims = new long[N];
        Object v = new Object();
        long t0 = System.nanoTime();
        for (int r = 0; r < R; r++) for (int i = 0; i < N; i++) refs[i] = v;
        long refMs = (System.nanoTime()-t0)/1_000_000;
        t0 = System.nanoTime();
        for (int r = 0; r < R; r++) for (int i = 0; i < N; i++) prims[i] = 7L;
        long primMs = (System.nanoTime()-t0)/1_000_000;
        System.out.printf("참조쓰기 %,5d ms   기본형쓰기 %,5d ms   차이 %,5d ms%n",
            refMs, primMs, refMs - primMs);
    }
}

